1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace App\Filament\Resources\Products\Schemas;
6	
7	use App\Models\Category2;
8	use App\Models\Environment;
9	use App\Models\Fabric;
10	use App\Models\Material;
11	use App\Models\Product;
12	use App\Models\ProductType;
13	use AtrioTeam\DigitalHub\Pim\AttributeSchema;
14	use AtrioTeam\DigitalHub\Pim\Filament\Schemas\AttributesEditor;
15	use AtrioTeam\DigitalHub\Pim\Filament\Schemas\NameAndId;
16	use AtrioTeam\DigitalHub\Pim\Filament\Schemas\OrphanAttributesAlert;
17	use AtrioTeam\DigitalHub\Tags\Enum\TagTarget;
18	use AtrioTeam\DigitalHub\Tags\Filament\TagPicker;
19	use Filament\Forms\Components\Select;
20	use Filament\Schemas\Components\Utilities\Get;
21	use Filament\Schemas\Schema;
22	
23	class ProductForm
24	{
25	    public static function configure(Schema $schema): Schema
26	    {
27	        return $schema
28	            ->components([
29	                NameAndId::make($schema),
30	                Select::make('category_2_id')
31	                    ->label(__('product.category_2'))
32	                    ->options(fn (): array => Category2::query()->pluck('name', 'id')->map(fn (mixed $name): string => is_scalar($name) ? (string) $name : '')->all())
33	                    ->default(fn (): mixed => request()->query('category_2'))
34	                    ->required()
35	                    ->searchable(),
36	                Select::make('product_type_id')
37	                    ->label(__('product.product_type'))
38	                    ->options(fn (): array => ProductType::query()->pluck('name', 'id')->map(fn (mixed $name): string => is_scalar($name) ? (string) $name : '')->all())
39	                    ->required()
40	                    ->searchable()
41	                    // reattivo: il cambio di tipologia rigenera l'editor degli attributi
42	                    // e (ri)valuta l'alert orfani sottostante
43	                    ->live(),
44	                Select::make('materials')
45	                    ->label(__('material.model_plural'))
46	                    ->relationship('materials', 'name')
47	                    ->options(fn (): array => Material::query()->pluck('name', 'id')->map(fn (mixed $name): string => is_scalar($name) ? (string) $name : '')->all())
48	                    ->multiple()
49	                    ->searchable()
50	                    ->preload(),
51	                Select::make('fabrics')
52	                    ->label(__('fabric.model_plural'))
53	                    ->relationship('fabrics', 'name')
54	                    ->options(fn (): array => Fabric::query()->pluck('name', 'id')->map(fn (mixed $name): string => is_scalar($name) ? (string) $name : '')->all())
55	                    ->multiple()
56	                    ->searchable()
57	                    ->preload(),
58	                Select::make('environments')
59	                    ->label(__('product.environments'))
60	                    ->relationship('environments', 'name')
61	                    ->options(fn (): array => Environment::query()->pluck('name', 'id')->map(fn (mixed $name): string => is_scalar($name) ? (string) $name : '')->all())
62	                    ->multiple()
63	                    ->searchable()
64	                    ->preload(),
65	                // solo i tag dei gruppi (product, entity) — vincolo rigido
66	                TagPicker::make((new Product())->getMorphClass(), TagTarget::Entity),
67	                // alert orfani: avvisa, al cambio tipologia, dei valori PIM che si
68	                // perderebbero perché non più previsti dal nuovo schema (vedi core).
69	                OrphanAttributesAlert::reactive($schema, self::schemaResolver()),
70	                AttributesEditor::reactive($schema, self::schemaResolver())->columnSpanFull()->columns(1),
71	            ]);
72	    }
73	
74	    /**
75	     * Resolver dello schema attributi corrente dal form state: legge
76	     * product_type_id e ritorna la AttributeSchema della tipologia selezionata
77	     * (o null). Condiviso da AttributesEditor::reactive() e OrphanAttributesAlert.
78	     *
79	     * @return \Closure(Get): ?AttributeSchema
80	     */
81	    private static function schemaResolver(): \Closure
82	    {
83	        return static function (Get $get): ?AttributeSchema {
84	            $class = self::schemaClassFor($get('product_type_id'));
85	
86	            return $class !== null ? new $class() : null;
87	        };
88	    }
89	
90	    /**
91	     * FQN della AttributeSchema associata a una tipologia, o null se non risolvibile.
92	     *
93	     * @return class-string<AttributeSchema>|null
94	     */
95	    private static function schemaClassFor(mixed $productTypeId): ?string
96	    {
97	        if (! is_numeric($productTypeId)) {
98	            return null;
99	        }
100	
101	        $class = ProductType::query()->find((int) $productTypeId)?->attribute_schema_class;
102	
103	        return is_string($class) && is_subclass_of($class, AttributeSchema::class) ? $class : null;
104	    }
105	}
